def test_migration_on_real_postgres(monkeypatch, postgres_dsn: str) -> None:
    """重复升级保持同一版本，验证 pgvector 和事务隔离级别。"""
    dsn = postgres_dsn
    monkeypatch.setenv("DATABASE_URL", dsn)
    config = Config(str(ROOT / "alembic.ini"))
    command.upgrade(config, "head")
    command.upgrade(config, "head")
    with psycopg.connect(dsn) as connection:
        assert 160000 <= connection.info.server_version < 170000
        assert connection.execute("SHOW transaction_isolation").fetchone() == ("read committed",)
        assert connection.execute("SELECT version_num FROM alembic_version").fetchall() == [
            ("0001_enable_pgvector",)
        ]
        assert connection.execute("SELECT '[1,2,3]'::vector <-> '[1,2,3]'::vector").fetchone() == (0.0,)
